package studio.shiren.mobile;
import android.content.Context;import android.media.*;import android.net.Uri;import java.io.*;import java.nio.*;import java.util.concurrent.atomic.AtomicBoolean;
final class CompatibleEncoder implements AutoCloseable {
 final PortableH264 codec;final int w,h;final File output,video;final Context context;final Uri source;final boolean sound;final AtomicBoolean cancel;final ByteBuffer yuv;final byte[] pixels;
 /* 初始化兼容编码通路。 */ CompatibleEncoder(Context context,Uri source,File output,int w,int h,int fps,boolean sound,AtomicBoolean cancel)throws Exception{this.context=context;this.source=source;this.output=output;this.w=w;this.h=h;this.sound=sound;this.cancel=cancel;video=sound?new File(output.getParent(),output.getName()+".video.mp4"):output;codec=new PortableH264(video,w,h,fps);yuv=ByteBuffer.allocateDirect(w*h*3/2);pixels=new byte[w*h*3/2];}
 /* 创建 YUV 输入缓冲区中指定区间的视图，不复制底层数据。 */ ByteBuffer slice(int offset,int length){ByteBuffer b=yuv.duplicate();b.position(offset);b.limit(offset+length);return b.slice();}
 /* 追加当前视频帧或音轨数据并维护时间戳。 */ void append(ByteBuffer rgba,int frame)throws Exception{VideoSource.check(cancel);int n=w*h;if(!NativeCore.rgbaToYuv(rgba,w,h,slice(0,n),w,1,slice(n,n/4),w/2,1,slice(n+n/4,n/4),w/2,1))throw new Exception("兼容编码转换失败");yuv.rewind();yuv.get(pixels);codec.append(pixels,frame);}
 /* 完成当前任务并释放编码或缓存资源。 */ void finish(float seconds)throws Exception{codec.finish();if(sound){remux(context,video,source,output,seconds,cancel);video.delete();}}
 /* 重新封装视频和音频而不改变视频效果。 */ static void remux(Context c,File video,Uri source,File output,float seconds,AtomicBoolean stop)throws Exception{MediaExtractor v=new MediaExtractor(),a=new MediaExtractor();MediaMuxer m=null;boolean started=false;try{v.setDataSource(video.getPath());a.setDataSource(c,source,null);int vi=-1,ai=-1;for(int i=0;i<v.getTrackCount();i++)if(v.getTrackFormat(i).getString(MediaFormat.KEY_MIME).startsWith("video/")){vi=i;break;}for(int i=0;i<a.getTrackCount();i++)if(a.getTrackFormat(i).getString(MediaFormat.KEY_MIME).startsWith("audio/")){ai=i;break;}if(ai<0){try(InputStream in=new FileInputStream(video);OutputStream out=new FileOutputStream(output)){byte[] b=new byte[65536];int n;while((n=in.read(b))>=0){VideoSource.check(stop);out.write(b,0,n);}}return;}if(!"audio/mp4a-latm".equals(a.getTrackFormat(ai).getString(MediaFormat.KEY_MIME)))throw new Exception("保留原声目前支持AAC；请关闭原声再导出。");m=new MediaMuxer(output.getPath(),0);int vt=m.addTrack(v.getTrackFormat(vi)),at=m.addTrack(a.getTrackFormat(ai));m.start();started=true;v.selectTrack(vi);a.selectTrack(ai);a.seekTo(0,MediaExtractor.SEEK_TO_NEXT_SYNC);copy(v,m,vt,seconds,stop);copy(a,m,at,seconds,stop);m.stop();started=false;}finally{v.release();a.release();if(m!=null){if(started)try{m.stop();}catch(Exception ignored){}m.release();}}}
 /* 将音视频轨样本复制到封装器，重新设置起始时间戳并响应取消。 */ static void copy(MediaExtractor e,MediaMuxer m,int track,float seconds,AtomicBoolean stop)throws Exception{ByteBuffer buffer=ByteBuffer.allocateDirect(8*1024*1024);MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();long first=e.getSampleTime();while(e.getSampleTime()>=0&&e.getSampleTime()-first<(long)(seconds*1000000)){VideoSource.check(stop);buffer.clear();int n=e.readSampleData(buffer,0);if(n<0)break;info.set(0,n,e.getSampleTime()-first,e.getSampleFlags());m.writeSampleData(track,buffer,info);if(!e.advance())break;}}
 /* 关闭当前对象持有的资源，避免重复占用文件、线程或设备。 */ public void close(){codec.close();if(!video.equals(output))video.delete();}
}
